<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Admin Users</h1><a class="btn btn-success" href="<?= url_to('admin.users.create') ?>">Create Admin</a></div><div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($admins as $admin): ?><tr><td><?= esc($admin['name']) ?></td><td><?= esc($admin['email']) ?></td><td><?= esc($admin['role_name']) ?></td><td><?= esc(ucfirst($admin['status'])) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url_to('admin.users.edit',$admin['id']) ?>">Edit</a><?php if((int)$admin['id']!==(int)session('admin_id')): ?><form class="d-inline" method="post" action="<?= site_url('admin/admin-users/'.$admin['id'].'/delete') ?>" onsubmit="return confirm('Delete this admin?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Delete</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div><?= $this->endSection() ?>
